  const WORD_RE=/[A-Za-z]+(?:['’][A-Za-z]+)?/g;
  const dictKey=word=>String(word||'').toLowerCase().replace(/[’]/g,"'");
  function dayKey(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
  function dictInfo(word){
    const key=dictKey(word);
    const x=DICT[key];
    return x || {ru:'Перевод уточняется в контексте',en:'Definition will be refined from context'};
  }
  function isSavedToday(word){const key=dictKey(word);return (st.dict||[]).some(x=>x.key===key&&x.lastClickedDay===dayKey())}
  function wordHtml(text, sentence){
    const raw=String(text??''), sent=sentence||raw; let out='',last=0,m;
    WORD_RE.lastIndex=0;
    while((m=WORD_RE.exec(raw))){
      out+=esc(raw.slice(last,m.index));
      const original=m[0],key=dictKey(original),disabled=isSavedToday(key)?' is-saved-today':'';
      out+='<button type="button" class="dict-word'+disabled+'" data-dict-word="'+esc(key)+'" data-dict-original="'+esc(original)+'" data-dict-sentence="'+esc(sent)+'">'+esc(original)+'</button>';
      last=m.index+original.length;
    }
    return out+esc(raw.slice(last));
  }
  function saveWord(word, sentence){
    const key=dictKey(word); const today=dayKey(); const info=dictInfo(key);
    st.dict=st.dict||[];
    let item=st.dict.find(x=>x.key===key);
    if(!item){item={key,unit:word,translation:info.ru,definition:info.en,firstContext:sentence||'',addedAt:Date.now(),lastClickedDay:today,status:'new',clicks:1,reviewCount:0};st.dict.unshift(item)}
    else {item.lastClickedDay=today;item.clicks=Math.max(0,Number(item.clicks)||0)+1;item.reviewCount=Math.max(0,Number(item.reviewCount)||0)+1;if(item.status==='new'&&item.clicks>=2)item.status='familiar';if(item.status==='familiar'&&item.reviewCount>=4)item.status='mastered';if(!item.firstContext)item.firstContext=sentence||'';if(!item.definition)item.definition=info.en;if(!item.translation)item.translation=info.ru;}
    save(); return item;
  }
  function showWordPopup(btn){
    const word=btn.dataset.dictWord, original=btn.dataset.dictOriginal, sentence=btn.dataset.dictSentence||'';
    const item=saveWord(word,sentence);
    document.querySelectorAll('.dict-word-popover').forEach(x=>x.remove());
    const pop=document.createElement('div');pop.className='dict-word-popover';
    pop.innerHTML='<div class="dict-pop-head"><b>'+esc(original)+'</b><button type="button" class="dict-pop-close" aria-label="Закрыть">×</button></div><div class="dict-pop-translation">'+esc(item.translation)+'</div><div class="dict-pop-definition">'+esc(item.definition)+'</div><div class="dict-pop-context">'+esc(sentence)+'</div><div class="dict-pop-note">Добавлено в личный словарь</div>';
    const host=btn.closest('.english-question,.english-option')||btn.parentElement; host.style.position='relative';host.appendChild(pop);
    pop.querySelector('.dict-pop-close').onclick=e=>{e.preventDefault();e.stopPropagation();pop.remove()};
    btn.classList.add('is-saved-today');btn.disabled=true;btn.setAttribute('aria-disabled','true');
  }
  function wireDictionaryWords(root){
    (root||document).querySelectorAll('.dict-word').forEach(b=>{b.onclick=e=>{e.preventDefault();e.stopPropagation();if(b.disabled||b.classList.contains('is-saved-today')||isSavedToday(b.dataset.dictWord||''))return;showWordPopup(b)}});
  }
  // Единый тренировочный банк: встроенная авторская практика + только действительно
  // проверенные встроенные записи source-bank. Метаданные внешних источников остаются
  // в каталоге и не ломают ежедневную тренировку переходом наружу.
  function localGrammarBank(){
    return Object.keys(GRAMMAR_PRACTICE).flatMap(title=>grammarPracticeFor(title));
  }
  const trainingBank=()=>[...localGrammarBank(),...bank.filter(sourceReady)];

  function pick(){
    const completedInSession=(st.session&&Array.isArray(st.session.done))?st.session.done:[];
    const usedAll=new Set(st.history.map(x=>x.taskId).filter(Boolean));
    const blocked=new Set([...usedAll,...completedInSession]);
    const errors={};
    st.history.forEach(x=>{if(x.correct===false)errors[x.topic]=(errors[x.topic]||0)+1});
    const eligible=trainingBank();
    let candidates=eligible.filter(x=>!blocked.has(x.id));
    let recycled=false;
    if(!candidates.length){
      // The source bank may recycle only after every source task has been seen.
      candidates=eligible.filter(x=>!completedInSession.includes(x.id));
      recycled=true;
    }
    const topicStats=new Map();
    st.history.forEach(x=>{
      if(!x||!x.topic)return;
      const q=topicStats.get(x.topic)||{correct:0,wrong:0};
      if(x.correct===true)q.correct++; else if(x.correct===false)q.wrong++;
      topicStats.set(x.topic,q);
    });
    candidates.sort((a,b)=>{
      const ea=errors[a.topic]||0, eb=errors[b.topic]||0;
      if(eb!==ea)return eb-ea;
      const sa=topicStats.get(a.topic)||{correct:0,wrong:0};
      const sb=topicStats.get(b.topic)||{correct:0,wrong:0};
      const da=Number(a.difficulty)||3, db=Number(b.difficulty)||3;
      // Repeated errors: prefer a slight rollback. Sustained success: prefer harder material.
      const dirA=sa.wrong>1?-1:sa.correct>2?1:0, dirB=sb.wrong>1?-1:sb.correct>2?1:0;
      if(dirA!==dirB)return dirB-dirA;
      if(dirA<0 && da!==db)return da-db;
      if(dirA>0 && da!==db)return db-da;
      return 0;
    });
    const target=candidates[0]||eligible[0];
    if(!target) throw new Error('English task bank is empty');
    const recentErr=topicStats.get(target.topic)?.wrong||0;
    const recentGood=topicStats.get(target.topic)?.correct||0;
    const adaptiveDifficulty=Math.max(1,Math.min(5,Number(target.difficulty||3)+(recentErr>1?-1:recentGood>2?1:0)));
    return Object.assign({},target,{difficulty:adaptiveDifficulty,_retried:false,_recycled:recycled});
  }

  function renderSourceCatalog(){
    const box=$('#englishTask'); if(!box)return;
    const all=eligibleBank();
    const sourceNames=[...new Set(all.map(t=>t.sourceName||'Источник'))].sort((a,b)=>a.localeCompare(b,'ru'));
    const topics=[...new Set(all.map(t=>topicLabel(t.topic||'')))].sort((a,b)=>a.localeCompare(b,'ru'));
    const statusLabel=t=>sourceReady(t)?'встроено':'внешний источник';
    const rows=all.slice(0,50).map(catalogRow).join('');
    box.innerHTML='<div class="source-catalog">'+
      '<div class="english-start"><span>SOURCE BANK · v13.25</span><h3>Каталог заданий</h3><div class="source-catalog-note"><b>'+all.length+' записей.</b> Здесь можно искать конкретное задание, фильтровать по источнику и учебной категории и сразу запускать выбранную запись. Текст внешних заданий не копируется в приложение.</div></div>'+
      '<div class="source-catalog-toolbar"><input id="sourceCatalogSearch" class="topic-search" placeholder="Поиск по источнику, теме или номеру…"><select id="sourceCatalogSource"><option value="">Все источники</option>'+sourceNames.map(x=>'<option value="'+esc(x)+'">'+esc(x)+'</option>').join('')+'</select><select id="sourceCatalogTopic"><option value="">Все темы</option>'+topics.map(x=>'<option value="'+esc(x)+'">'+esc(x)+'</option>').join('')+'</select></div>'+ 
      '<div class="source-catalog-summary" id="sourceCatalogSummary"></div>'+ 
      '<div class="source-catalog-list source-catalog-task-list" id="sourceCatalogList">'+rows+'</div>'+ 
      '<div class="source-catalog-more"><button class="ghost" id="sourceCatalogMore">Показать ещё 50</button></div>'+ 
      '<div class="english-start"><h3>Официальные навигаторы</h3><div class="source-catalog-list">'+FIPI_NAVIGATOR.map(x=>'<div class="source-catalog-row"><div><b>'+esc(x.title)+'</b><br><small>'+esc(x.ids)+'</small></div><a class="text-link" href="'+esc(x.url)+'" target="_blank" rel="noopener">Открыть ↗</a></div>').join('')+'</div></div>'+ 
      '<div class="english-answer-bar"><button class="ghost english-stop" id="englishStop">Закрыть</button></div></div>';
    let limit=50;
    const renderRows=()=>{
      const q=($('#sourceCatalogSearch')?.value||'').trim().toLowerCase();
      const src=$('#sourceCatalogSource')?.value||'';
      const tp=$('#sourceCatalogTopic')?.value||'';
      const filtered=all.filter(t=>{
        const label=topicLabel(t.topic||'');
        const hay=[t.id,t.sourceName,t.sourceQuestion,t.topic,label,t.level,t.type].join(' ').toLowerCase();
        return (!q||hay.includes(q))&&(!src||t.sourceName===src)&&(!tp||label===tp);
      });
      const visible=filtered.slice(0,limit);
      $('#sourceCatalogList').innerHTML=visible.map(catalogRow).join('')||'<div class="dict-empty">Ничего не найдено.</div>';
      $('#sourceCatalogSummary').textContent='Показано '+visible.length+' из '+filtered.length+' найденных записей';
      const more=$('#sourceCatalogMore');
      if(more){more.hidden=visible.length>=filtered.length;more.textContent=visible.length+50<filtered.length?'Показать ещё 50':'Показать ещё';}
      wireCatalogRows();
    };
    const reset=()=>{limit=50;renderRows()};
    $('#sourceCatalogSearch').oninput=reset;$('#sourceCatalogSource').onchange=reset;$('#sourceCatalogTopic').onchange=reset;
    $('#sourceCatalogMore').onclick=()=>{limit+=50;renderRows()};
    $('#englishStop')?.addEventListener('click',()=>{if(mode==='sources'){closeTraining()}else{stopTraining()}});
    renderRows();

    function catalogRow(t){
      const label=topicLabel(t.topic||'');
      const question=t.sourceQuestion!=null?'№ '+t.sourceQuestion:'';
      return '<article class="source-catalog-task" data-task-id="'+esc(t.id)+'"><div class="source-catalog-task-main"><div class="source-catalog-task-badges"><span class="source-status-pill">'+esc(t.level||'')+'</span><span class="source-status-pill">'+esc(statusLabel(t))+'</span></div><h4>'+esc(label)+'</h4><p>'+esc(t.sourceName||'Источник')+(question?' · '+esc(question):'')+'</p></div><div class="source-catalog-task-actions"><button class="primary catalog-open-task" data-task-id="'+esc(t.id)+'">Открыть задание</button><a class="text-link" href="'+esc(t.sourceUrl||'#')+(t.sourcePage?'#page='+encodeURIComponent(t.sourcePage):'')+'" target="_blank" rel="noopener">Источник ↗</a></div></article>';
    }
    function wireCatalogRows(){
      document.querySelectorAll('.catalog-open-task').forEach(b=>b.onclick=()=>{
        const t=all.find(x=>x.id===b.dataset.taskId); if(!t)return;
        mode='catalog';current=t;retrying=false;submitted=false;openTraining();renderCurrentTask(false);
      });
    }
  }

  function ensureOverlay(){
    let overlay=$('#englishFullscreen');
    if(!overlay){
      overlay=document.createElement('div');
      overlay.id='englishFullscreen';
      overlay.className='english-fullscreen';
      overlay.innerHTML='<div class="english-fullscreen-top"><div class="english-progress-wrap"><div class="english-progress-label" id="englishProgressText">Задание 1 из 10</div><div class="english-progress-track"><i id="englishProgressBar"></i></div></div><button class="english-close" id="englishClose" aria-label="Закрыть тренировку">×</button></div><main class="english-fullscreen-content" id="englishFullscreenContent"></main>';
      document.body.appendChild(overlay);
      $('#englishClose').onclick=()=>closeTraining();
    }
    return overlay;
  }
  function openTraining(){ensureOverlay().classList.add('open');document.body.classList.add('english-lock');}
  function closeTraining(){
    const destination=mode;
    const overlay=$('#englishFullscreen'); if(overlay)overlay.classList.remove('open');
    document.body.classList.remove('english-lock');
    current=null; manual=null; retrying=false; submitted=false; save();
    if(destination==='manual')renderTopic(); else if(destination==='catalog'||destination==='sources')renderSourceCatalog(); else render();
  }
  function setProgress(done,total){
    const label=$('#englishProgressText'),bar=$('#englishProgressBar');
    if(!label||!bar)return;
    if(total){label.textContent='Задание '+Math.min(done+1,total)+' из '+total;bar.style.width=Math.min(100,(done/total)*100)+'%';}
    else {label.textContent='Задание '+(done+1);bar.style.width='0%';}
  }

  function start(total=10){mode='ai';retrying=false;st.session={started:Date.now(),n:0,total,done:[],topic:null,currentTaskId:null,version:2};save();openTraining();renderTask();}

  // Source-task architecture.
  // Metadata-only source records stay in the catalog and are reachable through source-assisted training.
  // Once verified plain-text content is added, the same renderer makes every visible word clickable.
  function sourceHasContent(t){
    if(!t || !t.content || typeof t.content!=='object') return false;
    const c=t.content;
    return [c.prompt,c.passage,c.context,c.instructions].some(v=>typeof v==='string'&&v.trim()) || (Array.isArray(c.options)&&c.options.length>0);
  }
  function sourceContentParts(t){
    const c=t&&t.content||{};
    return {
      context:typeof c.context==='string'?c.context:'',
      instructions:typeof c.instructions==='string'?c.instructions:'',
      passage:typeof c.passage==='string'?c.passage:'',
      prompt:typeof c.prompt==='string'?c.prompt:'',
      options:Array.isArray(c.options)?c.options.map(String):[]
    };
  }
  function sourceReady(t){
    if(!t || !/^source-(mcq|input)$/.test(t.type)) return false;
    if(!sourceHasContent(t)) return false;
    const c=sourceContentParts(t);
    const visibleText=[c.instructions,c.context,c.passage,c.prompt,...c.options].join(' ').trim();
    if(!visibleText) return false;
    if(t.type==='source-mcq') return Array.isArray(c.options)&&c.options.length>0&&['letter','text'].includes(t.answerFormat)&&typeof t.answer==='string'&&t.answer.trim()!=='';
    if(t.type==='source-input') return Array.isArray(t.accepted)&&t.accepted.length>0;
    return false;
  }
  bank.forEach(t=>{ if(/^source-(mcq|input)$/.test(t.type) && !sourceReady(t)) t.active=false; });
  // Unified source-bank routing: every record is reachable from the training flow.
  // Metadata-only records are presented as source-assisted tasks rather than being
  // silently excluded. We never invent question text or answers.
  const eligibleBank=()=>bank.filter(t=>t && /^source-(mcq|input|link)$/.test(t.type));
  const isExternalSourceTask=t=>!!t && /^source-(mcq|input|link)$/.test(t.type) && !sourceReady(t);
  const hasVerifiedAnswer=t=>!!t && ((t.type==='source-mcq' && typeof t.answer==='string' && t.answer.trim() && t.answerFormat==='letter') || (t.type==='source-input' && Array.isArray(t.accepted) && t.accepted.length));

  function sourceTextBlock(label,text,sentence){
    return text ? '<section class="source-text-block"><div class="source-text-label">'+esc(label)+'</div><div class="source-text">'+wordHtml(text,sentence||text).replace(/\n/g,'<br>')+'</div></section>' : '';
  }
  function isCambridgePdf(t){return !!t&&/cambridgeenglish\.org\/.+\.pdf/i.test(String(t.sourceUrl||''))}
  function sourceTaskMarkup(t,retry=false){
    const c=sourceContentParts(t);
    if(!sourceReady(t)){
      const src=t.sourceUrl+(t.sourcePage?'#page='+t.sourcePage:'');
      const known=hasVerifiedAnswer(t);
      const answerUI=known
        ? (t.answerFormat==='letter'
          ? '<div class="english-external-answer"><label>Твой ответ</label><input id="englishAnswer" maxlength="4" placeholder="например, A"></div>'
          : '<div class="english-external-answer"><label>Твой ответ</label><input id="englishAnswer" placeholder="Введи ответ"></div>')
        : '<div class="source-selfcheck">У этого источника в банке нет проверенного ключа. Реши задание в оригинале. Завершение здесь фиксируется как «изучено», но не считается правильным ответом.</div>';
      const isPdf=/\.pdf(?:#|$)/i.test(src), useTopLevel=true;
      return (retry?'<div class="english-retry-label">Попробуй ещё раз</div>':'')+
        '<div class="source-task-note source-task-unready"><b>Реальная запись из банка</b><p>'+(useTopLevel?'Этот внешний источник нельзя надёжно встроить внутрь мобильного окна. Поэтому Via Classica открывает официальный источник в этой же вкладке; после возврата браузером текущая сессия сохраняется и ты продолжаешь с того же задания.':'Оригинал загружается прямо в это окно. Если внешний источник блокирует встраивание или отвечает слишком долго, появится резервный переход.')+'</p></div>'+
        '<div class="external-task-meta"><span>Задание № '+esc(t.sourceQuestion||'')+'</span><span>'+esc(t.sourceName||'Источник')+'</span></div>'+
        (useTopLevel?'<div class="source-launch-card"><b>Официальный источник готов к открытию</b><p>'+(isCambridgePdf(t)?'Cambridge B2 First: официальный раздел подготовки и sample tests.':'Оригинал задания по сохранённой ссылке.')+'</p><button type="button" class="primary" id="openOfficialSource">Открыть официальный источник ↗</button></div>':'<div class="source-iframe-wrap"><iframe class="source-task-iframe" src="'+esc(src)+'" title="Оригинальное задание из источника" loading="eager" referrerpolicy="no-referrer"></iframe></div>')+
        '<div class="source-iframe-actions"><a class="secondary-action source-open" href="'+esc(src)+'" target="_blank" rel="noopener">Открыть источник отдельно ↗</a></div>'+
        '<div class="source-task-note source-task-question"><b>Номер задания: '+esc(t.sourceQuestion||'')+'</b><p>Если источник показывает несколько вопросов, выполни именно указанный номер. После решения введи свой ответ ниже — Via Classica проверит его по сохранённому ключу.</p><p>Слова из внешнего задания нельзя надёжно сделать кликабельными внутри iframe: нужное слово можно добавить в словарь вручную через раздел «Словарь».</p></div>'+
        answerUI+
        (known?'<div class="english-answer-bar"><button class="primary" id="englishCheck" disabled>Проверить ответ</button><button class="secondary-action" id="externalDone">Завершить без проверки →</button><button class="ghost english-stop" id="englishStop">Остановить</button></div>':'<div class="english-answer-bar"><button class="primary" id="externalDone">Завершить задание →</button><button class="ghost english-stop" id="englishStop">Остановить</button></div>')+
        '<div id="englishFeedback"></div>';
    }
    const isLetter=t.answerFormat==='letter';
    const options=c.options.map((o,i)=>{
      const value=isLetter?String.fromCharCode(65+i):o;
      return '<div class="english-option" role="button" tabindex="0" data-answer="'+esc(value)+'"><span>'+String.fromCharCode(65+i)+'</span><b>'+wordHtml(o,c.prompt||c.passage||o)+'</b></div>';
    }).join('');
    const body=isLetter
      ? '<div class="english-options source-letter-options">'+options+'</div>'
      : '<textarea id="englishAnswer" rows="3" placeholder="'+(retry?'Попробуй ещё раз…':'Твой ответ…')+'"></textarea>';
    const attribution='<div class="source-task-note source-attribution"><b>Источник: '+esc(t.sourceName||'официальный источник')+'</b><a class="source-open" href="'+esc(t.sourceUrl+(t.sourcePage?'#page='+t.sourcePage:''))+'" target="_blank" rel="noopener">Оригинал ↗</a></div>';
    return (retry?'<div class="english-retry-label">Попробуй ещё раз</div>':'')+attribution+
      sourceTextBlock('Инструкция',c.instructions,c.instructions)+sourceTextBlock('Контекст',c.context,c.context)+sourceTextBlock('Текст',c.passage,c.passage)+sourceTextBlock('Вопрос',c.prompt,c.prompt)+
      body+'<div class="english-answer-bar"><button class="primary" id="englishCheck" disabled>Проверить ответ</button><button class="ghost english-stop" id="englishStop">Остановить</button></div><div id="englishFeedback"></div>';
  }
  function taskMarkup(t,retry=false){
    if(/^source-(mcq|input|link)$/.test(t.type)) return sourceTaskMarkup(t,retry);
    const isChoice=t.type==='mcq'||t.type==='reading';
    const body=isChoice
      ? '<div class="english-options">'+t.opts.map((o,i)=>'<div class="english-option" role="button" tabindex="0" data-answer="'+esc(o)+'"><span>'+String.fromCharCode(65+i)+'</span><b>'+wordHtml(o,t.q)+'</b></div>').join('')+'</div>'
      : '<textarea id="englishAnswer" rows="3" placeholder="'+(retry?'Попробуй ещё раз…':'Твой ответ…')+'"></textarea>';
    return (retry?'<div class="english-retry-label">Попробуй ещё раз</div>':'')+body+'<div class="english-answer-bar"><button class="primary" id="englishCheck" disabled>Проверить ответ</button><button class="ghost english-stop" id="englishStop">Остановить</button></div><div id="englishFeedback"></div>';
  }

  function taskHeading(t){
    if(/^source-(mcq|input|link)$/.test(t.type)) return 'Задание '+esc(t.sourceQuestion||'')+' · '+esc(t.sourceName||'Источник');
    return wordHtml(t.q||'',t.q||'');
  }
  function renderCurrentTask(retry=false){
    const box=$('#englishFullscreenContent');
    if(!box||!current) return;
    submitted=false;
    const title='<div class="english-task-heading"><small>'+(mode==='manual'?'ТРЕНИРОВКА ПО ТЕМЕ':mode==='catalog'?'БАНК ИСТОЧНИКОВ':'АДАПТИВНАЯ ТРЕНИРОВКА')+'</small></div>';
    const meta='<div class="task-meta"><span>'+esc(current.level||current.skill||'')+'</span><span>'+esc(topicLabel(current.topic||''))+'</span></div>';
    box.innerHTML=title+meta+'<h1 class="english-question">'+taskHeading(current)+'</h1>'+taskMarkup(current,retry);
    wireAnswer(); wireDictionaryWords(box);
    const progressDone=mode==='manual'?(manual?.answered||0):(st.session?.n||0); const progressTotal=mode==='manual'?(manual?.pool?.length||0):(st.session?.total||0); setProgress(progressDone,progressTotal);
  }
  function renderTask(){
    try{
      const resumable=st.session&&st.session.currentTaskId?trainingBank().find(x=>x.id===st.session.currentTaskId):null;
      current=resumable||pick();
    }
    catch(e){
      const box=$('#englishFullscreenContent');
      if(box) box.innerHTML='<div class="english-complete"><span>БАНК ОЖИДАЕТ ВСТРАИВАНИЯ</span><h1>Нет доступных записей банка.</h1><p>Банк пуст или повреждён.</p><button class="ghost english-stop" id="englishStop">Закрыть</button></div>';
      $('#englishStop')?.addEventListener('click',closeTraining); return;
    }
    retrying=false; submitted=false;
    if(st.session){st.session.currentTaskId=current.id;save()}
    renderCurrentTask(false);
  }
  function renderManualTask(retry=false){
    if(!manual||!manual.pool.length) return;
    // На повторной попытке остаёмся на том же задании. Нельзя брать
    // следующий элемент из pool: текущий уже отмечен в used при первом показе.
    if(retry && current && manual.pool.some(t=>t.id===current.id)){
      renderCurrentTask(true);
      return;
    }
    const available=manual.pool.filter(t=>!manual.used.includes(t.id));
    if(!available.length){ finishManual('done'); return; }
    current=available[0];
    manual.used.push(current.id);
    renderCurrentTask(false);
  }
  function wireAnswer(){
    const external=isExternalSourceTask(current);
    const isChoice=current.type==='mcq'||current.type==='reading'||(current.type==='source-mcq'&&current.answerFormat==='letter');
    let selected='';
    if(external){
      const input=$('#englishAnswer');
      if(input){ input.oninput=e=>{const check=$('#englishCheck'); if(check)check.disabled=!e.target.value.trim();}; }
      $('#openOfficialSource')?.addEventListener('click',()=>{try{sessionStorage.setItem('viaClassicaReturnTask',current.id)}catch(_){} window.location.href=current.sourceUrl+(current.sourcePage?'#page='+encodeURIComponent(current.sourcePage):'')});
      $('#externalDone')?.addEventListener('click',()=>{ record(null); appendNext(); });
      const frame=document.querySelector('.source-task-iframe');
      if(frame){
        const wrap=frame.parentElement;
        const showFallback=()=>{if(wrap?.querySelector('.source-iframe-fallback'))return;const note=document.createElement('div');note.className='source-iframe-fallback';note.innerHTML='<b>Источник не встроился вовремя.</b><p>Via Classica не подменяет оригинальное задание. Можно повторить загрузку здесь или открыть тот же официальный источник в новой вкладке.</p><div class="source-fallback-actions"><button type="button" class="secondary-action" id="sourceRetry">Повторить загрузку</button><a class="secondary-action" href="'+esc(src)+'" target="_blank" rel="noopener">Открыть источник отдельно ↗</a></div>';wrap?.appendChild(note);$('#sourceRetry')?.addEventListener('click',()=>{frame.src=src;note.remove();setTimeout(showFallback,7000)});};
        frame.addEventListener('load',()=>{frame.dataset.loaded='1';});
        frame.addEventListener('error',showFallback);
        setTimeout(()=>{if(frame.dataset.loaded!=='1')showFallback()},7000);
      }
      $('#englishCheck')?.addEventListener('click',()=>check($('#englishAnswer').value.trim()));
      $('#englishStop')?.addEventListener('click',stopTraining);
      return;
    }
    if(isChoice){
      document.querySelectorAll('.english-option').forEach(b=>{
        b.onclick=e=>{ if(e.target.closest('.dict-word')) return; document.querySelectorAll('.english-option').forEach(x=>x.classList.remove('selected')); b.classList.add('selected'); selected=b.dataset.answer; const check=$('#englishCheck'); if(check)check.disabled=false; };
        b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();b.click();}};
      });
    } else {
      const input=$('#englishAnswer');
      if(input)input.oninput=e=>{const check=$('#englishCheck');if(check)check.disabled=!e.target.value.trim()};
    }
    $('#englishCheck').onclick=()=>check(isChoice?selected:$('#englishAnswer').value.trim());
    $('#englishStop').onclick=stopTraining;
  }

  function normalize(s){return String(s||'').toLowerCase().replace(/[“”"'.,!?;:()\-]/g,' ').replace(/\s+/g,' ').trim()}
  function evaluate(task,answer){
    if(task.type==='source-mcq') return normalize(answer)===normalize(task.answer);
    if(task.type==='source-input') return Array.isArray(task.accepted)&&task.accepted.some(x=>normalize(answer)===normalize(x));
    if(task.a) return normalize(answer)===normalize(task.a);
    if(task.id==='w1') return /\bprimary sources?\b/i.test(answer)&&/\b(evidence|information|insight|perspective|record|material|direct|firsthand|original|period|past|historical|context)\b/i.test(answer);
    if(task.id==='t1') return /(?:would like|i['’]d like|wanted to|want to|could i|may i|can i)/i.test(answer)&&/(?:meeting|appointment)/i.test(answer)&&/(?:reschedul|move|change|postpone|put off)/i.test(answer);
    if(task.id==='c2') return /(?:pay|payment).*(?:by|with|using)\s+(?:a\s+)?(?:credit|debit)?\s*card/i.test(answer)||/can i\s+pay\s+with\s+(?:a\s+)?card/i.test(answer);
    return !!answer;
  }

  function record(correct){
    st.history.push({taskId:current.id,topic:current.topic,skill:current.skill,correct,ts:Date.now()});
    if(mode==='manual' && manual && (correct===true || correct===false)){ manual.answered++; if(correct) manual.correct++; }
    if(mode==='ai'){if(!st.session.done.includes(current.id))st.session.done.push(current.id);st.session.n++;st.session.currentTaskId=null}
    save();
  }

  function feedbackHtml(correct,firstTry,answer){
    if(correct){
      const better=current.type==='input' && current.ex && normalize(answer)!==normalize(current.ex);
      return '<div class="feedback good"><div class="feedback-title">✓ Верно</div>'+(better?'<button class="feedback-link" id="betterBtn">Как лучше?</button>':'')+'<button class="feedback-link" id="whyBtn">Почему?</button></div>';
    }
    if(firstTry){
      return '<div class="feedback retry"><div class="feedback-title">Не совсем.</div><p>Попробуй исправить ответ ещё раз.</p><button class="secondary-action" id="retryBtn">Попробовать ещё</button></div>';
    }
    const right=current.type==='source-mcq'?current.answer:(current.type==='source-input'?(current.accepted||[]).join(' / '):(current.a||current.ex));
    return '<div class="feedback bad"><div class="feedback-title">Не совсем.</div><p><b>Правильный ответ:</b> '+esc(right||'см. ключ источника')+'</p><button class="feedback-link" id="whyBtn">Почему?</button></div>';
  }

  function wireWhy(){
    $('#whyBtn')?.addEventListener('click',()=>toggleExplain('why'));
    $('#betterBtn')?.addEventListener('click',()=>toggleExplain('better'));
  }
  function toggleExplain(kind){
    const existing=$('#englishExplain'); if(existing){existing.remove();return}
    const text=(current.type==='source-mcq'||current.type==='source-input') ? 'Ответ проверен по ключу указанного официального источника.\n\nОригинал задания и его контекст находятся по кнопке «Открыть источник».' : (kind==='better'?'Более естественный вариант: '+current.ex+'\n\nНюанс: этот вариант звучит естественно в данном контексте.':'Почему подходит: '+current.why+'\n\nПример: '+current.ex);
    const el=document.createElement('div');el.id='englishExplain';el.className='explain-box';
    el.innerHTML='<b>'+(kind==='better'?'Как лучше':'Почему?')+'</b>'+text.split('\n\n').map(p=>'<p>'+esc(p)+'</p>').join('');
    $('#englishFeedback').appendChild(el);
  }

  function check(answer){
    if(!current||!answer||submitted||($('#englishCheck')&&$('#englishCheck').disabled))return;
    submitted=true;
    const checkBtn=$('#englishCheck'); if(checkBtn) checkBtn.disabled=true;
    const correct=evaluate(current,answer),fb=$('#englishFeedback');
    if(correct){record(true);fb.innerHTML=feedbackHtml(true,false,answer);wireWhy();appendNext();return}
    if(!retrying){retrying=true;fb.innerHTML=feedbackHtml(false,true);$('#englishCheck').disabled=true;$('#retryBtn').onclick=()=>mode==='manual'?renderManualTask(true):renderRetry();return}
    record(false);fb.innerHTML=feedbackHtml(false,false);wireWhy();appendNext();
  }

  function renderRetry(){ renderCurrentTask(true); }


  function finishManual(reason='stop'){
    if(!manual) return;
    const isGrammar=!!manual.isGrammar;
    const title=isGrammar?(manual.grammarTitle||manual.topic.replace(/^Грамматика · /,'')):manual.topic;
    const answered=manual.answered||0, correct=manual.correct||0;
    const total=manual.pool?.length||0;
    const remaining=Math.max(0,total-manual.used.length);
    const box=$('#englishFullscreenContent');
    if(!box)return;
    const again=isGrammar?'<button class="primary" id="againGrammar">Пройти ещё 5</button>':'';
    box.innerHTML='<div class="english-complete"><span>'+(reason==='done'?'ТЕМА ЗАВЕРШЕНА':'ТРЕНИРОВКА ЗАВЕРШЕНА')+'</span><h1>'+esc(title)+'</h1><p><b>'+correct+' из '+answered+'</b> отвечено правильно.'+(remaining?' Осталось заданий: '+remaining+'.':' Все доступные задания пройдены.')+'</p><div class="english-actions">'+again+'<button class="ghost" id="manualTopics">К темам</button></div></div>';
    if(isGrammar)$('#againGrammar').onclick=()=>startGrammarPractice(title,grammarPracticeFor(title));
    $('#manualTopics').onclick=()=>{closeTraining();renderTopic()};
  }
  function stopTraining(){
    if(mode==='manual' && manual){ finishManual('stop'); return; }
    closeTraining();
  }

  function appendNext(){
    if(!$('#englishFeedback')) return;
    const wrap=document.createElement('div');wrap.className='english-next';
    const isDone=mode==='ai'&&st.session.n>=st.session.total;
    const isCatalog=mode==='catalog';
    wrap.innerHTML='<button class="primary" id="nextEnglish">'+(isDone?'Завершить тренировку':isCatalog?'Вернуться в каталог':'Дальше →')+'</button>';
    $('#englishFeedback').appendChild(wrap);
    $('#nextEnglish').onclick=()=>isDone?finish():isCatalog?(closeTraining(),renderSourceCatalog()):mode==='ai'?renderTask():manualNext();
    if(mode==='ai')setProgress(st.session.n,st.session.total);
  }

  function finish(){
    if(!st.session){render();return}
    const total=st.session.total,last=st.history.slice(-total),errs={};
    last.filter(x=>x.correct===false).forEach(x=>errs[x.topic]=(errs[x.topic]||0)+1);
    const top=Object.entries(errs).sort((a,b)=>b[1]-a[1]).slice(0,2).map(x=>x[0]);
    st.profile.active=top; st.session=null; save();
    const box=$('#englishFullscreenContent');
    const bar=$('#englishProgressBar'); if(bar)bar.style.width='100%';
    const label=$('#englishProgressText'); if(label)label.textContent=total+' из '+total;
    box.innerHTML='<div class="english-complete"><span>СЕССИЯ ЗАВЕРШЕНА</span><h1>'+total+' заданий пройдено.</h1><p>'+(top.length?'Сейчас стоит немного усилить: '+esc(top.join(' · '))+'.':'Сегодня явной повторяющейся проблемы не видно.')+'</p><div class="english-actions"><button class="primary" id="again5">Ещё 5</button><button class="ghost" id="profileGo">Профиль</button></div></div>';
    $('#again5').onclick=()=>start(5);
    $('#profileGo').onclick=()=>{closeTraining();renderProfile()};
  }

  function nav(page){
    if(typeof window.showViaPage==='function'){ window.showViaPage(page); return; }
    document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id===page));
    const title=document.querySelector('#title');
    if(title && page==='english') title.textContent='Английский';
  }

  function renderProfile(){
    nav('english');const box=$('#englishTask'),errs={};
    st.history.forEach(x=>{if(x.correct===false)errs[x.topic]=(errs[x.topic]||0)+1});
    const top=Object.entries(errs).sort((a,b)=>b[1]-a[1]).slice(0,3).map(x=>x[0]);
    box.innerHTML='<div class="english-profile"><span>МОЙ ПРОФИЛЬ</span><h3>'+(st.profile.cefr?esc(st.profile.cefr)+' — '+({A1:'Beginner',A2:'Elementary',B1:'Intermediate',B2:'Upper-Intermediate',C1:'Advanced',C2:'Proficient'}[st.profile.cefr]||'уровень определён'):'Профиль формируется')+'</h3><p>Профиль формируется по истории тренировок. Встроенная грамматика и проверенные source-bank задания учитываются в общей истории.</p>'+(top.length?'<h4>Сейчас стоит усилить</h4><ul>'+top.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'<p>Устойчивых повторяющихся ошибок пока немного.</p>')+'<button class="text-link" id="profileMore">Подробнее</button></div>';
    $('#profileMore').onclick=()=>{const el=document.createElement('div');el.className='explain-box';el.innerHTML='<b>Подробнее</b><p>В полноценной версии здесь появится расширенная картина по Grammar, Vocabulary, Reading, Listening, Writing и contextual use. Сейчас профиль хранится локально.</p>';box.appendChild(el)};
  }

  function renderDictionary(){
    nav('english'); const box=$('#englishTask'); const list=st.dict||[];
    const cards=list.map((x,i)=>'<article class="dict-card"><div class="dict-card-head"><b>'+esc(x.unit)+'</b><span class="dict-status">'+esc(x.status==='mastered'?'освоено':x.status==='familiar'?'знакомо, требует практики':'новое')+'</span></div><strong>'+esc(x.translation||'—')+'</strong><div class="dict-definition">'+esc(x.definition||'')+'</div><p>'+esc(x.firstContext||'Контекст пока не сохранён.')+'</p><div class="dict-card-actions"><button type="button" class="text-link dict-delete" data-dict-index="'+i+'">Удалить</button></div></article>').join('');
    box.innerHTML='<div class="english-profile dictionary-page"><span>СЛОВАРЬ</span><h3>Личные слова и выражения</h3><p>Нажми слово в английском задании — оно сразу попадёт сюда. Словарь сохраняется на этом устройстве.</p><div class="dict-add"><input id="dictManualWord" class="topic-search" placeholder="Добавить слово или фразу…"><button class="primary" id="dictManualAdd">Добавить</button></div><div class="dict-toolbar"><input id="dictSearch" class="topic-search" placeholder="Поиск в словаре…"><select id="dictFilter"><option value="newest">Сначала новые</option><option value="alpha">По алфавиту</option><option value="new">Новые</option><option value="familiar">Требуют практики</option><option value="mastered">Освоено</option></select></div><div id="dictList">'+(cards||'<div class="dict-empty">Пока нет записей. Нажми на любое английское слово в задании.</div>')+'</div></div>';
    const renderFiltered=()=>{
      const q=($('#dictSearch')?.value||'').trim().toLowerCase(), f=$('#dictFilter')?.value||'newest';
      let arr=(st.dict||[]).filter(x=>!q || x.unit.toLowerCase().includes(q) || (x.translation||'').toLowerCase().includes(q));
      if(f==='alpha')arr.sort((a,b)=>a.unit.localeCompare(b.unit)); else if(f!=='newest')arr=arr.filter(x=>x.status===f);
      else arr.sort((a,b)=>(b.addedAt||0)-(a.addedAt||0));
      $('#dictList').innerHTML=arr.length?arr.map(x=>{const i=st.dict.indexOf(x);return '<article class="dict-card"><div class="dict-card-head"><b>'+esc(x.unit)+'</b><span class="dict-status">'+esc(x.status==='mastered'?'освоено':x.status==='familiar'?'знакомо, требует практики':'новое')+'</span></div><strong>'+esc(x.translation||'—')+'</strong><div class="dict-definition">'+esc(x.definition||'')+'</div><p>'+esc(x.firstContext||'Контекст пока не сохранён.')+'</p><div class="dict-card-actions"><button type="button" class="text-link dict-delete-filtered" data-dict-index="'+i+'">Удалить</button></div></article>'}).join(''):'<div class="dict-empty">Ничего не найдено.</div>';
    };
    $('#dictSearch').oninput=renderFiltered; $('#dictFilter').onchange=renderFiltered;
    $('#dictManualAdd').onclick=()=>{const v=$('#dictManualWord').value.trim(); if(!v)return; const key=dictKey(v); let item=st.dict.find(x=>x.key===key); if(item){item.unit=v;if(!item.firstContext)item.firstContext='Добавлено вручную';} else {item=saveWord(v,'Добавлено вручную');} save(); renderDictionary();};
    const dictList=$('#dictList'); if(dictList) dictList.onclick=e=>{const b=e.target.closest('.dict-delete,.dict-delete-filtered'); if(!b)return; const i=Number(b.dataset.dictIndex); if(Number.isInteger(i)&&st.dict[i]){st.dict.splice(i,1);save();renderDictionary();}};
  }
